graph.schema:
type Coop {
    id: ID
    farmId: String
    name: String
    capacity: Int
    farm: Farm
    hens: [Hen]
}

type Farm {
    id: ID
    name: String
}

type Hen {
    id: ID
    name: String
}

type Query {
    getCoop(id: ID, at: Float): Coop
    getCoops(name: String, at: Float): [Coop]
    getCoopsByFarm(id: ID, at: Float): [Coop]
}

type Farm {
    id: ID
    name: String
    address: String
    coops: [Coop]
}

type Coop {
    id: ID
    name: String
}

type Query {
    getFarm(id: ID, at: Float): Farm
    getFarms(name: String, at: Float): [Farm]
}

type Hen {
    id: ID
    coopId: String
    name: String
    dateOfBirth: String
    coop: Coop
    layReports: [LayReport]
    productivity: [HenProductivity]
}

type Coop {
    id: ID
    name: String
}

type LayReport {
    id: ID
    eggs: Int
    timeOfDay: String
}

type HenProductivity {
    id: ID
    totalEggs: Int
    lastLaidAt: String
}

type Query {
    getHen(id: ID, at: Float): Hen
    getHens(name: String, at: Float): [Hen]
    getHensByCoop(id: ID, at: Float): [Hen]
}

type HenProductivity {
    id: ID
    henId: String
    totalEggs: Int
    lastLaidAt: String
    hen: Hen
}

type Hen {
    id: ID
    name: String
}

type Query {
    getHenProductivity(id: ID, at: Float): HenProductivity
    getHenProductivities(at: Float): [HenProductivity]
    getHenProductivityByHen(id: ID, at: Float): [HenProductivity]
}

type LayReport {
    id: ID
    henId: String
    eggs: Int
    timeOfDay: String
    hen: Hen
}

type Hen {
    id: ID
    name: String
}

type Query {
    getLayReport(id: ID, at: Float): LayReport
    getLayReports(at: Float): [LayReport]
    getLayReportsByHen(id: ID, at: Float): [LayReport]
}
